fn contains_consecutive_numbers(a: &[i32]) -> bool {
    // We need at least two elements to have an adjacent pair
    if a.len() < 2 {
        return false;
    }

    // Check each adjacent pair
    for window in a.windows(2) {
        // window[0] is a[i], window[1] is a[i+1]
        if window[1] == window[0].wrapping_add(1) {
            return true;
        }
    }

    false
}

